const comps = $input.first().json.props || [];
const targetSqft = $('Webhook - Comp Analysis').first().json.body.squareFootage || 1500;
const targetBeds = $('Webhook - Comp Analysis').first().json.body.bedrooms || 3;

// Filter comps within reasonable range
const filtered = comps.filter(c => {
  if (!c.livingArea || !c.price) return false;
  const sqftDiff = Math.abs(c.livingArea - targetSqft) / targetSqft;
  return sqftDiff < 0.25; // Within 25% of target sqft
}).slice(0, 10);

const prices = filtered.map(c => c.price);
const avgPrice = prices.length ? prices.reduce((a, b) => a + b, 0) / prices.length : 0;
const medianPrice = prices.length ? prices.sort((a, b) => a - b)[Math.floor(prices.length / 2)] : 0;
const pricePerSqft = filtered.map(c => c.price / c.livingArea);
const avgPricePerSqft = pricePerSqft.length ? pricePerSqft.reduce((a, b) => a + b, 0) / pricePerSqft.length : 0;

return [{
  json: {
    compCount: filtered.length,
    suggestedArv: Math.round(medianPrice),
    averagePrice: Math.round(avgPrice),
    medianPrice: Math.round(medianPrice),
    averagePricePerSqft: Math.round(avgPricePerSqft),
    suggestedArvFromSqft: Math.round(avgPricePerSqft * targetSqft),
    dataQuality: filtered.length >= 3 ? 'good' : filtered.length >= 1 ? 'limited' : 'insufficient',
    comps: filtered.map(c => ({
      address: c.address,
      price: c.price,
      sqft: c.livingArea,
      beds: c.bedrooms,
      baths: c.bathrooms,
      pricePerSqft: Math.round(c.price / c.livingArea),
    }))
  }
}];
